ControlflowRule.Definition:

state enter (start);
state createXML : "statedesc.abap.istream.created";
state dtdRestrictionDisabled : "statedesc.abap.dtd.restriction.disabled";
state dtdRestrictionEnabled;
state parserHandler;
state validationDisabled : "statedesc.abap.dtd.validation.disabled";
state validationEnabled;
state validationXMLMissing (error) : "statedesc.abap.parser.parsed";
var istream;
var istream2;
var parser;
var parser2;
enter -> createXML { istream = $createIstreamString(...) }
enter -> createXML { $createIstreamString(istream2,...) }
createXML -> dtdRestrictionDisabled { istream.$setDTDRestrictionFalse(...) | istream2.$setDTDRestrictionFalse(...) }
createXML -> dtdRestrictionEnabled { istream.$setDTDRestrictionTrue(...) | istream2.$setDTDRestrictionTrue(...) }
dtdRestrictionDisabled -> dtdRestrictionEnabled { istream.$setDTDRestrictionTrue(...) | istream2.$setDTDRestrictionTrue(...) }
dtdRestrictionEnabled -> dtdRestrictionDisabled { istream.$setDTDRestrictionFalse(...) | istream2.$setDTDRestrictionFalse(...) }
dtdRestrictionDisabled -> parserHandler { parser = $createParser(?,istream,...) | parser2 = $createParser(?,istream2,...)  }
parserHandler -> validationDisabled { parser.$setValidatingDisabled(...) | parser2.$setValidatingDisabled(...)}
parserHandler -> validationEnabled { parser.$setValidatingEnabled(...) | parser2.$setValidatingEnabled(...) }
validationDisabled -> validationEnabled { parser.$setValidatingEnabled(...) | parser2.$setValidatingEnabled(...)}
validationEnabled -> validationDisabled { parser.$setValidatingDisabled(...) | parser2.$setValidatingDisabled(...) }
validationDisabled -> validationXMLMissing { parser.$parsing(...) | parser2.$parsing(...) | parser.$parsing2(...) | parser2.$parsing2(...) }


state enter (start);
state initial : "statedesc.abap.resource.acquired";
state released;
state end_of_scope (error) : "statedesc.abap.resource.leaked";
var s;
var c;
enter -> initial { $openResource(...,s,...) }
enter -> initial { c = $openResource(...) }
initial -> released { s.$releaseResource(...) | c.$releaseResource(...)}
initial -> end_of_scope { #end_scope(s) | #end_scope(c) }


state enter (start);
state initial : "statedesc.abap.resource.acquired";
state released;
state end_of_scope (error) : "statedesc.abap.resource.leaked";
var s;
var c;
enter -> initial { $openResource(s,...) }
enter -> initial { c = $openResource(...) }
initial -> released { s.$releaseResource(...) | c.$releaseResource(...)}
initial -> end_of_scope { #end_scope(s) | #end_scope(c) }


state enter (start);
state initial : "statedesc.abap.dbconnection.acquired";
state released;
state end_of_scope (error) : "statedesc.abap.db.leaked";
var s;
var c;
enter -> initial { $openResource(s,...) }
enter -> initial { c = $openResource(...) }
initial -> released { s.$releaseResource(...) | c.$releaseResource(...)}
initial -> end_of_scope { #end_scope(s) | #end_scope(c) }

            state begin (start);			
			state initial : "statedesc.abap.hashFunction.instantiated";
			state update : "statedesc.abap.hashFunction.updated";
			state error (error) : "statedesc.abap.hashFunction.finalizedWithoutUpdate";
            var s;
			var c;

			begin -> initial {$doInit(...,s,...)}			
			begin -> initial {c = $doInit(...)}			
			initial -> update {s.$doUpdate(...)|c.$doUpdate(...)}
            initial -> error {s.$doFinalize(...)|c.$doFinalize(...)}

